const { applyReleaseSigning } = require('../withReleaseSigning');

// Excerpt of android/app/build.gradle generated by the Expo SDK 58 template.
const TEMPLATE = `
android {
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            minifyEnabled enableMinifyInReleaseBuilds
        }
    }
}
`;

describe('applyReleaseSigning', () => {
  it('signs release builds with the upload keystore when configured, else with the debug key', () => {
    const result = applyReleaseSigning(TEMPLATE);
    expect(result).toContain("def storeFilePath = findProperty('TALLY_UPLOAD_STORE_FILE')");
    expect(result).toMatch(
      /release \{[^}]*signingConfig findProperty\('TALLY_UPLOAD_STORE_FILE'\) \? signingConfigs\.release : signingConfigs\.debug/,
    );
    expect(result).toMatch(/gradle\.taskGraph\.whenReady[\s\S]*shared debug key/);
  });

  it('keeps debug builds signed with the debug key', () => {
    const result = applyReleaseSigning(TEMPLATE);
    expect(result).toMatch(/debug \{\s+signingConfig signingConfigs\.debug\s+\}/);
  });

  it('is idempotent', () => {
    const once = applyReleaseSigning(TEMPLATE);
    expect(applyReleaseSigning(once)).toBe(once);
  });

  it('fails loudly when the template no longer matches', () => {
    expect(() => applyReleaseSigning('android { }')).toThrow(/withReleaseSigning/);
  });
});
